package com.johnny.hotel.cms;
import com.johnny.hotel.exception.BusinessException;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.web.multipart.MultipartFile;import java.nio.file.*;import java.security.MessageDigest;import java.util.*;
@Service public class LocalMediaStorageService implements MediaStorageService{
 private final Path root;private final long max;public LocalMediaStorageService(@Value("${hotel.cms.media.local-root:./data/cms-media}")String root,@Value("${hotel.cms.media.max-bytes:52428800}")long max){this.root=Path.of(root).toAbsolutePath().normalize();this.max=max;}
 public Stored store(MultipartFile f,String type){try{if(f==null||f.isEmpty()||f.getSize()>max)throw new BusinessException("Invalid media size");String name=Optional.ofNullable(f.getOriginalFilename()).orElse("");if(name.contains("..")||name.contains("/")||name.contains("\\"))throw new BusinessException("Invalid media filename");String ext=name.contains(".")?name.substring(name.lastIndexOf('.')+1).toLowerCase(Locale.ROOT):"";String mime=Optional.ofNullable(f.getContentType()).orElse("").toLowerCase(Locale.ROOT);var allowed=Map.of("IMAGE",Set.of("jpg:image/jpeg","jpeg:image/jpeg","png:image/png","webp:image/webp"),"VIDEO",Set.of("mp4:video/mp4","webm:video/webm"),"MODEL_3D",Set.of("glb:model/gltf-binary","gltf:model/gltf+json","glb:application/octet-stream","gltf:application/octet-stream"));if(!allowed.containsKey(type)||!allowed.get(type).contains(ext+":"+mime))throw new BusinessException("Unsupported media type");byte[] bytes=f.getBytes();if(!signature(ext,bytes))throw new BusinessException("Media content does not match its declared type");String checksum=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));String key=UUID.randomUUID()+"."+ext;Files.createDirectories(root);Path target=root.resolve(key).normalize();if(!target.getParent().equals(root))throw new BusinessException("Invalid storage key");Files.write(target,bytes,StandardOpenOption.CREATE_NEW);return new Stored(key,"/api/public/site/media/"+key,bytes.length,checksum);}catch(BusinessException e){throw e;}catch(Exception e){throw new BusinessException("Media storage failed");}}
 private boolean signature(String ext,byte[] b){return switch(ext){case"jpg","jpeg"->b.length>=3&&(b[0]&255)==0xff&&(b[1]&255)==0xd8&&(b[2]&255)==0xff;case"png"->b.length>=8&&(b[0]&255)==0x89&&b[1]==0x50&&b[2]==0x4e&&b[3]==0x47;case"webp"->b.length>=12&&ascii(b,0,"RIFF")&&ascii(b,8,"WEBP");case"mp4"->b.length>=8&&ascii(b,4,"ftyp");case"webm"->b.length>=4&&(b[0]&255)==0x1a&&(b[1]&255)==0x45&&(b[2]&255)==0xdf&&(b[3]&255)==0xa3;case"glb"->b.length>=4&&ascii(b,0,"glTF");case"gltf"->b.length>1&&(b[0]=='{'||b[0]=='[');default->false;};}private boolean ascii(byte[]b,int at,String s){if(b.length<at+s.length())return false;for(int i=0;i<s.length();i++)if(b[at+i]!=(byte)s.charAt(i))return false;return true;}
}
